    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Dinos", "Prevents wild creatures from being spawned. Enabling this option will make the following options unusable: -NoDinosExceptForcedSpawn, -NoDinosExceptStreamingSpawn, -NoDinosExceptManualSpawn and -NoDinosExceptWaterSpawn."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Dinosaur Downloads", "If enabled, this will prevent downloading dinosaurs from the server."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Dinosaur Uploads", "If enabled, this will prevent uploading dinosaurs."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Item Downloads", "If enabled, this will prevent downloading items from the server."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Item Uploads", "If enabled, this will prevent uploading items."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Survivor Downloads", "If enabled, this will prevent downloading survivors from the server."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Survivor Uploads", "If enabled, this will prevent uploading survivors."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "No Transfer From Filtering", "Prevents ARK Data usage between single player and servers that do not have a cluster ID. Even with a cluster ID set, keep this enabled to fully disable code paths that allow it."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Official map", "Pick a stock ASA map, or type a custom/mod map below."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Override Dino Upload Expiration (minutes)", "Set, in minutes, the expiration timer for uploaded dinosaurs in ARK Data. If set to 0 or lower, the server will revert to default. Warning: do not set this option to an extremely high value; it can overflow and may cause upload time checks to fail and ARK Data to be deleted."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Override Item Upload Expiration (minutes)", "Set, in minutes, the expiration timer for uploaded items in ARK Data. If set to 0 or lower, the server will revert to default. Warning: do not set this option to an extremely high value; it can overflow and may cause upload time checks to fail and ARK Data to be deleted."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Override Survivor Upload Expiration (minutes)", "Enable to write tribute character expiration in minutes. Warning: do not set this option to an extremely high value; it can overflow and may cause upload time checks to fail and ARK Data to be deleted."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Peer port:", "Peer port (always Game port +1), used for connecting to the server from the client."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Query port:", "The port Steam uses to communicate with your server. Default is 27015. Change this and Server Port if you wish to host multiple servers on one machine."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "RCON", "Enable RCON (Remote Console) for this server. This allows you to execute admin/cheat commands on the server."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "RCON port:", "The port that RCON will use on your server."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "RCON Server Game Log Buffer", "Determines how many lines of game logs are send over the RCON."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Server Locale", "Override the server locale. This does not affect the client locale."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Server name:", "Public name of the server"),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Server password:", "The password users must enter in order to access the server. If this is set, only people who know the password can access your server."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Server port:", "The port users will use to connect to your server. Default is 7777. Change this and Query Port if you wish to host multiple servers on one machine."),
    OptionSearchEntry(ServerDetailsTab.GENERAL, "Slots:", "Sets the maximum number of players which can join this server."),
