    OptionSearchEntry(ServerDetailsTab.MANAGEMENT, "Restart after crash", "Automatically restart the server if it crashes, this is done within 5 seconds of the server crashing."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Crafting Skill Bonus Multiplier", "Scales the bonus received from upgrading the Crafting Skill."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Crafting Speed", "Specifies multiplier for crafting speed gained per level. Higher values increase Crafting Speed faster; lower values increase Crafting Speed slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Enable Flyer-Carry", "If enabled, allows flying creatures to pick up wild creatures in PvE."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Food", "Specifies multiplier for food gained per level. Higher values increase Food faster; lower values increase Food slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Fortitude", "Specifies multiplier for fortitude gained per level. Higher values increase Fortitude faster; lower values increase Fortitude slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Health", "Specifies multiplier for health gained per level. Higher values increase Health faster; lower values increase Health slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Implant suicide cooldown (seconds)", "Cooldown before a survivor can use the implant to suicide. Default is 28800 (8 hours)."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Max Fall Speed Multiplier", "Defines the falling speed multiplier at which players starts taking fall damage. The higher this setting is, the longer players can fall without taking fall damage."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Melee Damage", "Specifies multiplier for melee damage gained per level. Higher values increase Melee Damage faster; lower values increase Melee Damage slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Movement Speed", "Specifies multiplier for movement speed gained per level. Higher values increase Movement Speed faster; lower values increase Movement Speed slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Oxygen", "Specifies multiplier for oxygen gained per level. Higher values increase Oxygen faster; lower values increase Oxygen slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Oxygen swim speed multiplier", "Scales how much the oxygen stat contributes to swim speed."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Per-Level Stats Multipliers", "If enabled, changes amount of stats gained for each level."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Base Stat Multipliers", "If enabled, changes player base stats by multiplying default values. This affects start stats for new spawned characters."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Damage Multiplier", "Specifies the scaling factor for the damage players deal with their attacks. The default value 1 provides normal damage. Higher values increase damage. Lower values decrease it."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Food Drain Multiplier", "Specifies the scaling factor for player characters' food consumption. Higher values increase food consumption (player characters get hungry faster)."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Harvesting Damage Multiplier", "Scales the damage done to a harvestable item/entity by a Player. A higher value increases it (by percentage): the higher number, the faster the survivors collects."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Health Recovery Multiplier", "Specifies the scaling factor for player characters' health recovery. Higher values increase the recovery rate (player characters heal faster)."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Resistance Multiplier", "Specifies the scaling factor for the resistance to damage players receive when attacked. The default value 1 provides normal damage. Higher values decrease resistance, increasing damage per attack. Lower values increase it, reducing damage per attack."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Stamina Drain Multiplier", "Specifies the scaling factor for player characters' stamina consumption. Higher values increase stamina consumption (player characters get tired faster)."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Player Water Drain Multiplier", "Specifies the scaling factor for player characters' water consumption. Higher values increase water consumption (player characters get thirsty faster)."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Stamina", "Specifies multiplier for stamina gained per level. Higher values increase Stamina faster; lower values increase Stamina slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Temperature", "Specifies multiplier for temperature gained per level. Higher values increase Temperature faster; lower values increase Temperature slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Torpidity", "Specifies multiplier for torpidity gained per level. Higher values increase Torpidity faster; lower values increase Torpidity slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Water", "Specifies multiplier for water gained per level. Higher values increase Water faster; lower values increase Water slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "Weight", "Specifies multiplier for weight gained per level. Higher values increase Weight faster; lower values increase Weight slower."),
    OptionSearchEntry(ServerDetailsTab.PLAYER, "XP Multiplier", "Specifies the scaling factor for the experience received by players, tribes and tames for various actions. Higher values increase XP amounts awarded for various actions."),
    OptionSearchEntry(ServerDetailsTab.PROFILE, "Enable ASA API", "Enables Ark Ascended Server API, which allows the use of plugins. These are not the same as mods. Requires reinstall."),
    OptionSearchEntry(ServerDetailsTab.PROFILE, "Installation path:", "Path to the server installation folder, changing this will not move the existing installation."),
    OptionSearchEntry(ServerDetailsTab.PROFILE, "Profile name:", null),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow Cancelling Tribe Warfare", "If enabled, allows cancellation of an agreed-upon war before it has started."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow Crate Spawns on Top of Structures", "If enabled, allows from-the-air Supply Crates to appear on top of Structures, rather than being prevented by Structures"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow Creative Mode", "If Enabled, adds a button to the pause menu to enable/disable creative mode."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow Custom Recipes", "If enabled, allows custom RP-oriented Recipe/Cooking System (including Skill-Based results)."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow flyer speed leveling", "If enabled, flyers can spend points on movement speed."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow multiple C4 per creature", "If enabled, more than one C4 can be attached to a creature."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow speed leveling", "If enabled, players can spend points on movement speed."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow structures at supply drops", "If enabled, players can build near supply drops on PvE servers."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow Tribe Alliances", "If enabled, allows tribes to officially declare alliances with each other."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow Tribe Warfare", "If enabled, tribes can officially declare war on each other for mutually-agreed-upon periods (PvE)."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Allow unlimited respecs", "If enabled, players can respec without a cooldown."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Custom Recipe Effectiveness Multiplier", "Scales the effectiveness of custom recipes. A higher value increases (by percentage) their effectiveness."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Custom Recipe Skill Multiplier", "Scales the effect of the players crafting speed level that is used as a base for the formula in creating a custom recipe. A higher number increases (by percentage) the effect."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Disable dino decay in PvE", "If enabled, unclaimed dinos do not decay on PvE servers."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Disable PvE Friendly Fire", "If enabled prevents Friendly-Fire in PvE (among tribe mates/tames/structures)"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Disable PvP Friendly Fire", "If enabled prevents Friendly-Fire in PvP (among tribe mates/tames/structures)"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Disable structure placement collision", "If enabled, structures can clip into terrain."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Disable Supply drops", "If enabled, prevents spawning of Loot crates (artifact creates will still spawn)"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Enable Diseases", "If enabled, completely enables diseases on the server."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Enable Hardcore Mode", "Enables Hardcore mode (player characters revert to level 1 upon death)"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Enable PvE", "If enabled, disables PVP and enables PvE"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Enable PvE Cave Building", "If enabled, allows building in caves when PvE mode is also enabled"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Enable PvE Cryo Sickness", "If enabled, enables Cryopod cooldown timer when deploying a creature in PvE."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Enable PvP Cave Building", "If enabled, allows building in caves when PvP mode is also enabled"),
    OptionSearchEntry(ServerDetailsTab.RULES, "Flying stamina recovery", "If enabled, stamina recovers while standing on a flyer."),
