    OptionSearchEntry(ServerDetailsTab.RULES, "Ignore prevention volumes", "If enabled, structures can be built inside prevention volumes."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Max Alliances Per Tribe", "If set, defines maximum alliances a tribe can form. A value of 0 means no limit."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Max Players In Tribe", "Sets the maximum survivors allowed in a tribe. A value of 1 effectively disables tribes. The default value of 0 means there is no limit."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Max Tribes Per Alliance", "If set, defines maximum number of tribes allowed in an alliance. A value of 0 means no limit."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Non-Permanent Diseases", "If enabled, makes permanent diseases not permanent. Players will lose them if on re-spawn."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Offline protection interval (seconds)", "Grace period after logging out before offline protection ends. 0 uses ARK's default."),
