    OptionSearchEntry(ServerDetailsTab.RULES, "Prevent offline PvP", "If enabled, players are protected from PvP while offline."),
    OptionSearchEntry(ServerDetailsTab.RULES, "PvE dino decay period multiplier", "Scales the PvE dino decay period."),
