    OptionSearchEntry(ServerDetailsTab.RULES, "Tribe Name Change Cooldown", "Value passed to ARK unchanged. The unit is ambiguous: the wiki says minutes, but the published official value (172800 = 2 days) only makes sense as seconds. Default is 15. Verify the unit on your server before relying on a duration."),
    OptionSearchEntry(ServerDetailsTab.RULES, "Tribe Slot Reuse Cooldown (minutes)", "Locks a tribe slot for the value in seconds, e.g. 3600 means 1 hour. The manager displays this in minutes. Used on Official Small Tribes servers."),
